<template>
  <view class="page"><jk-page-nav title="盘点详情"/><view class="content"><view class="status"><jk-status-tag :text="statusText" :tone="tone"/><text>{{data.checkNo}}</text><small>{{hint}}</small></view><view class="card"><view class="metrics"><view><text>账面</text><strong>{{data.bookTotalQty||0}}</strong></view><view><text>实盘</text><strong>{{data.actualTotalQty||0}}</strong></view><view><text>盘盈</text><strong>{{data.profitQty||0}}</strong></view><view><text>盘亏</text><strong>{{data.lossQty||0}}</strong></view></view></view><view class="card"><view class="title">库存明细</view><view v-for="item in data.items||[]" :key="item.id" class="item"><view class="main"><text>{{item.skuCode||('商品'+item.productId)}}</text><text>账面可用 {{item.bookAvailableQty}} · 冻结 {{item.bookFrozenQty}}</text></view><view v-if="data.status==='DRAFT'" class="actual"><text>实盘</text><input v-model.number="item.actualAvailableQty" type="number"/></view><view v-else class="diff"><strong>{{item.actualAvailableQty}}</strong><text :class="item.differenceQty<0?'loss':'profit'">差异 {{item.differenceQty>0?'+':''}}{{item.differenceQty}}</text></view></view></view><view class="card"><view class="title">处理记录</view><view v-for="log in data.auditLogs||[]" :key="log.id" class="log"><text>{{log.action}}</text><text>{{log.remark||log.afterStatus}}</text><small>{{log.createTime}}</small></view></view><button v-if="data.status==='DRAFT'" class="submit" :disabled="submitting" @tap="submit">提交实盘并冻结库存</button></view></view>
</template>
<script>
import JkPageNav from '@/components/jk/jk-page-nav.vue';import JkStatusTag from '@/components/jk/jk-status-tag.vue';import{getJkStockCheckDetail,submitJkStockCheck}from'@/api/jkV31.js';
export default{components:{JkPageNav,JkStatusTag},data(){return{id:null,data:{},submitting:false}},computed:{statusText(){return{DRAFT:'待实盘',SUBMITTED:'待后台审核',COMPLETED:'已完成',REJECTED:'已驳回'}[this.data.status]||this.data.status},tone(){return this.data.status==='COMPLETED'?'success':this.data.status==='SUBMITTED'?'warning':this.data.status==='REJECTED'?'danger':'info'},hint(){return this.data.status==='DRAFT'?'填写全部实际可用数量后提交':this.data.status==='SUBMITTED'?'库存账户处于盘点冻结，等待后台审核':this.data.status==='COMPLETED'?'差异已通过库存流水完成调整':'盘点已解冻，可重新发起'}},onLoad(o){this.id=o.id},onShow(){this.load()},methods:{value(r){return(r&&r.data)||r||{}},load(){getJkStockCheckDetail(this.id).then(r=>{this.data=this.value(r);(this.data.items||[]).forEach(x=>{if(x.actualAvailableQty===null||x.actualAvailableQty===undefined)this.$set(x,'actualAvailableQty',x.bookAvailableQty)})})},submit(){const items=(this.data.items||[]).map(x=>({checkItemId:x.id,actualAvailableQty:Number(x.actualAvailableQty),remark:''}));if(items.some(x=>Number.isNaN(x.actualAvailableQty)||x.actualAvailableQty<0))return uni.showToast({title:'请填写全部实盘数量',icon:'none'});uni.showModal({title:'提交实盘',content:'提交后库存账户将冻结，审核完成前不能订货、调拨或销售。',success:r=>{if(r.confirm){this.submitting=true;submitJkStockCheck({checkId:this.data.id,items,remark:'本人提交实盘'}).then(()=>{uni.showToast({title:'已提交审核'});this.load()}).finally(()=>this.submitting=false)}}})}}}
</script>
<style scoped>.page{min-height:100vh;background:#f7f9f9}.content{padding:18rpx 22rpx 44rpx}.status{display:flex;flex-direction:column;align-items:center;padding:28rpx;border-radius:20rpx;background:#fff}.status>text{margin-top:14rpx;font-size:24rpx;font-weight:700}.status small{margin-top:9rpx;color:#8e989c;font-size:20rpx}.card{margin-top:18rpx;padding:24rpx;border-radius:20rpx;background:#fff}.metrics{display:flex}.metrics view{display:flex;flex:1;flex-direction:column;align-items:center;border-right:1rpx solid #edf1f0}.metrics view:last-child{border-right:0}.metrics text{color:#899398;font-size:20rpx}.metrics strong{margin-top:8rpx;font-size:28rpx}.title{font-size:27rpx;font-weight:700}.item{display:flex;align-items:center;justify-content:space-between;padding:20rpx 0;border-bottom:1rpx solid #edf1f0}.main text,.diff text{display:block}.main text:first-child{font-size:24rpx;font-weight:700}.main text:last-child{margin-top:7rpx;color:#879196;font-size:20rpx}.actual{display:flex;align-items:center;gap:10rpx;color:#7d888d;font-size:21rpx}.actual input{width:120rpx;height:58rpx;border-radius:12rpx;background:#f3f7f6;text-align:center}.diff{text-align:right}.diff strong{font-size:25rpx}.diff text{margin-top:6rpx;font-size:20rpx}.profit{color:#0fa981}.loss{color:#d95555}.log{padding:16rpx 0;border-bottom:1rpx solid #edf1f0}.log text,.log small{display:block}.log text:first-child{font-size:23rpx;font-weight:700}.log text:nth-child(2){margin-top:5rpx;color:#69757a;font-size:21rpx}.log small{margin-top:5rpx;color:#a0a9ad;font-size:19rpx}.submit{height:82rpx;margin-top:20rpx;border-radius:41rpx;background:#16b990;color:#fff;font-size:25rpx;line-height:82rpx}.submit::after{border:0}</style>
